// The simulation runs in Buffers 0 and 1 (see their tabs). This draws its latest step,
// lighting the pattern as if V were raised up from the surface.
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 px = 1. / iResolution.xy;
  vec2 uv = fragCoord * px;
  float v = texture(iBuffer1, uv).g;
  vec2 slope = vec2(
    texture(iBuffer1, uv + vec2(px.x, 0.)).g - texture(iBuffer1, uv - vec2(px.x, 0.)).g,
    texture(iBuffer1, uv + vec2(0., px.y)).g - texture(iBuffer1, uv - vec2(0., px.y)).g);
  float light = 1. + 4. * dot(slope, vec2(-0.6, 0.8));
  vec3 low = vec3(0.04, 0.05, 0.12);
  vec3 high = vec3(0.98, 0.62, 0.28);
  vec3 col = mix(low, high, smoothstep(0.08, 0.35, v)) * light;
  fragColor = vec4(col, 1.);
}

