// Gray-Scott reaction-diffusion. Two chemicals, U (red) and V (green), spread out and react:
// V feeds on U, U is topped up at the feed rate, and V dies off at the kill rate.
// Buffers 0 and 1 each take one step, reading the other, so it runs two steps a frame.
#define previous iBuffer1
#define feed iFloat0
#define kill iFloat1

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  if (iFrame == 0) {
    // Start with U everywhere, and V in a scattering of small spots.
    vec2 cell = floor(fragCoord / 20.);
    vec2 centre = (cell + 0.25 + 0.5 * vec2(hash(cell), hash(cell + 7.))) * 20.;
    float v = hash(cell + 3.) < 0.4 && length(fragCoord - centre) < 3. ? 1. : 0.;
    fragColor = vec4(1., v, 0., 1.);
    return;
  }
  vec2 px = 1. / iResolution.xy;
  vec2 uv = fragCoord * px;
  vec2 here = texture(previous, uv).rg;
  // How different each point is from its neighbours (the Laplacian), which drives the spreading.
  vec2 spread = -here
    + 0.2 * (texture(previous, uv + vec2(px.x, 0.)).rg + texture(previous, uv - vec2(px.x, 0.)).rg
           + texture(previous, uv + vec2(0., px.y)).rg + texture(previous, uv - vec2(0., px.y)).rg)
    + 0.05 * (texture(previous, uv + px).rg + texture(previous, uv - px).rg
            + texture(previous, uv + vec2(px.x, -px.y)).rg + texture(previous, uv - vec2(px.x, -px.y)).rg);
  float reaction = here.x * here.y * here.y;
  float u = here.x + 1.0 * spread.x - reaction + feed * (1. - here.x);
  float v = here.y + 0.5 * spread.y + reaction - (kill + feed) * here.y;
  fragColor = vec4(clamp(vec2(u, v), 0., 1.), 0., 1.);
}

